import * as T from '../vendor/three.module.js';
export function createMirrors(renderer,scene,car){
 const mirrorScene=new T.Scene(),screenCamera=new T.OrthographicCamera(-1,1,1,-1,0,1);
 const material=new T.ShaderMaterial({uniforms:{map:{value:null},aspect:{value:2}},vertexShader:'varying vec2 vUv; void main(){vUv=uv; gl_Position=vec4(position.xy,0.,1.);}',fragmentShader:'uniform sampler2D map; uniform float aspect; varying vec2 vUv; void main(){vec2 p=(vUv-.5)*vec2(aspect,1.);vec2 q=abs(p)-vec2(aspect*.5-.10,.40);float d=length(max(q,0.))+min(max(q.x,q.y),0.)-.10;if(d>0.)discard;gl_FragColor=texture2D(map,vec2(1.-vUv.x,vUv.y));}',depthTest:false,depthWrite:false});
 const plane=new T.Mesh(new T.PlaneGeometry(2,2),material);mirrorScene.add(plane);
 const mirrors=[['rear-mirror',0,1.4,.8,0,50,384,128],['left-mirror',-1.05,1.03,-.45,.24,64,192,112],['right-mirror',1.05,1.03,-.45,-.24,64,192,112]].map(([id,x,y,z,angle,fov,w,h])=>({element:document.getElementById(id),offset:new T.Vector3(x,y,z),angle,camera:new T.PerspectiveCamera(fov,w/h,.25,550),target:new T.WebGLRenderTarget(w,h,{depthBuffer:true,stencilBuffer:false}),rect:null}));
 let next=0,timer=0;
 function resize(){for(const m of mirrors)m.rect=m.element.getBoundingClientRect();}
 resize();
 return {resize,update(dt,state,force=false,low=false){timer+=dt;if(timer<(low?.075:.035)&&!force)return;timer=0;const m=mirrors[next++%mirrors.length];const wasExterior=car.exterior.visible,wasInterior=car.interior.visible;car.root.visible=false;const offset=m.offset.clone().applyAxisAngle(new T.Vector3(0,1,0),state.yaw);m.camera.position.set(state.x+offset.x,state.y+offset.y,state.z+offset.z);const a=state.yaw+m.angle;m.camera.lookAt(m.camera.position.x+Math.sin(a)*70,m.camera.position.y-1,m.camera.position.z+Math.cos(a)*70);const shadow=renderer.shadowMap.autoUpdate;renderer.shadowMap.autoUpdate=false;renderer.setRenderTarget(m.target);renderer.clear();renderer.render(scene,m.camera);renderer.setRenderTarget(null);renderer.shadowMap.autoUpdate=shadow;car.root.visible=true;car.exterior.visible=wasExterior;car.interior.visible=wasInterior;},draw(){renderer.autoClear=false;renderer.setScissorTest(true);for(const m of mirrors){const rect=m.rect;if(!rect||!rect.width)continue;const b=innerHeight<=540&&innerWidth>innerHeight?5:innerWidth<600?5:7;const x=rect.left+b,y=innerHeight-rect.bottom+b,w=rect.width-b*2,h=rect.height-b*2;renderer.setViewport(x,y,w,h);renderer.setScissor(x,y,w,h);material.uniforms.map.value=m.target.texture;material.uniforms.aspect.value=w/h;renderer.render(mirrorScene,screenCamera);}renderer.setScissorTest(false);renderer.setViewport(0,0,innerWidth,innerHeight);renderer.autoClear=true;}};
}
